#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    // Unsigned integers
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    // Signed integers
    Int8,
    Int16,
    Int32,
    Int64,
    // Floating-point
    Float16,
    Float32,
    Float64,
    // Complex
    Complex64,
    Complex128,
}

pub fn min_scalar_type(value: i8) -> NumpyDType {
    // Since all types are at least 8 bits and Int8 covers [-128, 127],
    // the only question is unsigned vs. signed for non-negative values.
    if value >= 0 {
        NumpyDType::UInt8
    } else {
        NumpyDType::Int8
    }
}

